H.background();
const n = Math.max(3, Math.round(P.n));
const cx = H.W/2, cy = H.H*0.56, R = 150;
const rot = -Math.PI/2 + 0.15*Math.sin(t*0.4);
const pts = [];
for (let i = 0; i < n; i++){
  const a = rot + i*2*Math.PI/n;
  pts.push([cx + R*Math.cos(a), cy + R*Math.sin(a)]);
}
const sum = (n-2)*180;
const each = sum/n;
H.text("Interior angle sum = (n - 2) * 180", 24, 30, {color:H.colors.ink, size:18, weight:700});
H.text("Each diagonal from one vertex cuts the n-gon into n - 2 triangles.", 24, 52, {color:H.colors.sub, size:13});
H.path(pts, {close:true, fill:"rgba(124,196,255,0.14)", color:H.colors.accent, width:2.5});
for (let i = 2; i < n-1; i++){
  H.line(pts[0][0], pts[0][1], pts[i][0], pts[i][1], {color:H.colors.violet, width:1, dash:[4,4]});
}
const hi = Math.floor(t*0.8) % n;
H.circle(pts[hi][0], pts[hi][1], 6, {fill:H.colors.warn, stroke:H.colors.bg, width:2});
H.text(each.toFixed(0) + "°", pts[hi][0], pts[hi][1]-14, {color:H.colors.warn, size:12, align:"center"});
H.text("n = " + n + "   triangles = " + (n-2), 24, 76, {color:H.colors.good, size:13});
H.text("sum = (" + n + " - 2) * 180 = " + sum + "°", 24, 96, {color:H.colors.accent2, size:14});
H.text("each interior angle = " + each.toFixed(1) + "°", 24, 116, {color:H.colors.violet, size:13});
